#include <iostream>
#include <vector>

using namespace std;

int L, C, P;
bool is_black[7][7];
bool is_eligible[7][7];
int id[7][7];

vector<vector<int>> adj;
vector<int> match;
vector<bool> visited;

int dr[] = {-1, 1, 0, 0};
int dc[] = {0, 0, -1, 1};

bool dfs(int u) {
    for (int v : adj[u]) {
        if (visited[v]) continue;
        visited[v] = true;
        if (match[v] < 0 || dfs(match[v])) {
            match[v] = u;
            return true;
        }
    }
    return false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    if (!(cin >> L >> C)) return 0;
    cin >> P;

    for (int i = 0; i < P; ++i) {
        int r, c;
        cin >> r >> c;
        is_black[r][c] = true;
    }

    int total_eligible = 0;
    for (int r = 1; r <= L; ++r) {
        for (int c = 1; c <= C; ++c) {
            if (is_black[r][c]) continue;
            bool adj_black = false;
            for (int d = 0; d < 4; ++d) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr >= 1 && nr <= L && nc >= 1 && nc <= C && is_black[nr][nc]) {
                    adj_black = true;
                    break;
                }
            }
            if (adj_black) {
                is_eligible[r][c] = true;
                id[r][c] = total_eligible++;
            }
        }
    }

    adj.resize(total_eligible);

    for (int r = 1; r <= L; ++r) {
        for (int c = 1; c <= C; ++c) {
            if (!is_eligible[r][c]) continue;
            if ((r + c) % 2 == 0) {
                for (int d = 0; d < 4; ++d) {
                    int nr = r + dr[d];
                    int nc = c + dc[d];
                    if (nr >= 1 && nr <= L && nc >= 1 && nc <= C && is_eligible[nr][nc]) {
                        adj[id[r][c]].push_back(id[nr][nc]);
                    }
                }
            }
        }
    }

    match.assign(total_eligible, -1);
    int max_matching = 0;

    for (int r = 1; r <= L; ++r) {
        for (int c = 1; c <= C; ++c) {
            if (is_eligible[r][c] && (r + c) % 2 == 0) {
                visited.assign(total_eligible, false);
                if (dfs(id[r][c])) {
                    max_matching++;
                }
            }
        }
    }

    int ans = total_eligible - max_matching;
    cout << ans << "\n";

    return 0;
}
